  'User blocked. Their content and notifications are hidden.' => 'བཀོལ་སྤྱོད་པས་བཀག་འགོག་བྱས། ཁོང་ཚོའི་ནང་དོན་དང་བརྡ་ཁྱབ་གསང་བ་བྱས་ཡོད།',
