  'This channel has not added an about section yet.' => 'བརྙན་འཕྲིན་ཁང་འདིས་ད་དུང་སྐོར་གྱི་སྡེ་ཚན་ཁ་སྣོན་བྱས་མེད།',
  'Admin' => 'འཛིན་སྐྱོང་པ།',
