  'System Settings' => 'མ་ལག་གི་སྒྲིག་བཀོད།',
  'Monitor platform activity, moderation, revenue, and system health.' => 'སྟེགས་བུའི་བྱེད་སྒོ་དང་ཚོད་འཛིན་དང་ཡོང་འབབ་དང་མ་ལག་གི་འཕྲོད་བསྟེན་ལ་ལྟ་ཞིབ་བྱེད།',
  'Manage and monitor platform users, permissions, and activity.' => 'སྡིངས་ཆའི་སྤྱོད་མཁན་དང་ཆོག་མཆན་དང་བྱེད་སྒོ་དོ་དམ་དང་ལྟ་རྟོག་བྱེད།',
  'Manage creators, channel performance, verification, and creator growth.' => 'གསར་གཏོད་པ་དང་རྒྱུ་ལམ་གྱི་ནུས་པ་དང་བདེན་དཔང་དང་གསར་གཏོད་ཀྱི་འཕེལ་རྒྱས་ལ་དོ་དམ་བྱེད།',
  'Manage videos, shorts, posts, and content moderation across the platform.' => 'སྟེགས་བུའི་ཐོག་བརྙན་འཕྲིན་དང་ཐུང་ཐུང་དང་རྩོམ་ཡིག་དང་ནང་དོན་དོ་དམ་དོ་དམ་བྱེད།',
  'Monitor live sessions, scheduling, stream health, and live moderation.' => 'ཐད་གཏོང་ཚོགས་འདུ་དང་དུས་ཚོད་གཏན་འཁེལ་དང་འཕྲོད་བསྟེན་དང་ཐད་གཏོང་དོ་དམ་ལ་ལྟ་རྟོག་བྱེད།',
  'Review flagged content, user complaints, and platform safety incidents.' => 'ནང་དོན་དང་སྤྱོད་མཁན་གྱི་སྐྱོན་བརྗོད་དང་སྟེགས་བུའི་བདེ་འཇགས་དོན་རྐྱེན་ལ་བསྐྱར་ཞིབ་བྱོས།',
  'Track revenue, payouts, subscriptions, ads, tips, and creator earnings.' => 'ཡོང་འབབ་དང་དངུལ་སྤྲོད་དང་མངགས་ཉོ་དང་ཁྱབ་བསྒྲགས་དང་བསླབ་བྱ་དང་བཟོ་མཁན་གྱི་ཡོང་འབབ་རྗེས་འདེད་བྱེད།',
  'Analyze platform growth, viewer behavior, engagement, and content performance.' => 'སྡིངས་ཆའི་འཕེལ་རྒྱས་དང་ལྟ་མཁན་གྱི་སྤྱོད་ལམ་དང་འབྲེལ་གཏུག་དང་ནང་དོན་གྱི་ནུས་པ་ལ་དབྱེ་ཞིབ་བྱོས།',
  'Manage support tickets, help requests, escalations, and response quality.' => 'རྒྱབ་སྐྱོར་གྱི་འཛིན་བྱང་དང་རོགས་རམ་གྱི་རེ་འདུན་དང་འཕེལ་རྒྱས་དང་ལན་འདེབས་ཀྱི་སྤུས་ཚད་དོ་དམ་བྱེད།',
  'Manage admin roles, access levels, team members, and security permissions.' => 'འཛིན་སྐྱོང་འགན་འཁུར་དང་འཛུལ་ཞུགས་གནས་རིམ་དང་རུ་ཁག་གི་ཚོགས་མི་དང་བདེ་འཇགས་ཆོག་མཆན་དོ་དམ་བྱེད།',
  'Configure platform preferences, integrations, security, storage, and system behavior.' => 'སྡིངས་ཆའི་དགའ་མོས་དང་མཉམ་བསྲེས་དང་བདེ་འཇགས་དང་གསོག་འཇོག་དང་མ་ལག་གི་སྤྱོད་ཚུལ་རྣམས་སྒྲིག་བཀོད་བྱེད།',
  'Loading admin data...' => 'དོ་དམ་པའི་གཞི་གྲངས་ངོ་མ་མངོན་བཞིན་ཡོད།',
  'Sign in with an admin account to view this page.' => 'ཤོག་ངོས་འདི་ལ་གཟིགས་ཆེད་འཛིན་སྐྱོང་རྩིས་ཁྲ་བརྒྱུད་ནས་ཐོ་འགོད་བྱོས།',
