  'Explore tools and tips to grow faster, improve your channel, and reach more viewers.' => 'ལག་ཆ་དང་བསླབ་བྱ་འཚོལ་ཞིབ་བྱས་ནས་མགྱོགས་པོ་འཕེལ་རྒྱས་འགྲོ་རྒྱུ་དང་། ཁྱེད་རང་གི་བརྙན་འཕྲིན་ཡར་རྒྱས་གཏོང་རྒྱུ། དེ་བཞིན་ལྟ་མཁན་མང་བ་ལ་སླེབས་རྒྱུ་ཡིན།',
  'Loading growth data...' => 'འཕེལ་རྒྱས་ཀྱི་གྲངས་ཐོ་མངོན་བཞིན་ཡོད།',
