  'Discovery videos' => 'གསར་རྙེད་བརྙན་འཕྲིན།',
  'Growth actions' => 'འཕེལ་རྒྱས་ཀྱི་བྱ་སྤྱོད།',
  'Based on your channel data' => 'ཁྱེད་རང་གི་རྒྱུད་ལམ་གྱི་གཞི་གྲངས་གཞིར་བཟུང་།',
  'Publish consistently' => 'རྒྱུན་མཐུད་ངང་པར་སྐྲུན་བྱེད་པ།',
  'Upload your first video and give viewers a clear reason to subscribe.' => 'ཁྱེད་རང་གི་བརྙན་འཕྲིན་ཐོག་མ་དེ་བླུགས་ནས་ལྟ་མཁན་ཚོར་མངགས་ཉོ་བྱེད་པའི་རྒྱུ་མཚན་གསལ་པོ་ཞིག་སྤྲོད་དགོས།',
  'Use Shorts for discovery' => 'གསར་རྙེད་ཀྱི་ཆེད་དུ་ཐུང་ཐུང་བེད་སྤྱོད་བྱེད།',
  'Keep testing quick hooks and link viewers to longer videos.' => 'མགྱོགས་མྱུར་གྱི་གཅུས་གཟེར་ཚོད་ལྟ་བྱེད་པ་དང་ལྟ་མཁན་རྣམས་བརྙན་འཕྲིན་རིང་བོ་ལ་འབྲེལ་མཐུད་བྱེད་རོགས།',
  'Create short vertical videos to reach viewers who have not found your channel yet.' => 'ཁྱེད་རང་གི་བརྙན་འཕྲིན་ཁང་ད་དུང་མ་རྙེད་པའི་ལྟ་མཁན་ཚོར་སླེབས་ཆེད་ལངས་པའི་བརྙན་ཐུང་ཐུང་ཐུང་བཟོས།',
  'Create short' => 'ཐུང་ཐུང་བཟོས།',
  'Turn comments into loyalty' => 'མཆན་བུ་རྣམས་ལྷག་བསམ་རྣམ་པར་བསྒྱུར་བ།',
  'Reply to recent comments and turn viewers into returning fans.' => 'ཉེ་ཆར་གྱི་མཆན་ལ་ལན་འདེབས་བྱས་ནས་ལྟ་མཁན་རྣམས་དགའ་མོས་ཅན་དུ་བསྒྱུར་དགོས།',
  'Ask a question in your next upload and reply quickly when comments arrive.' => 'ཁྱེད་རང་གི་ཡར་བསྐུར་རྗེས་མའི་ནང་དྲི་བ་ཞིག་དྲིས་ནས་མཆན་འགྲེལ་སླེབས་སྐབས་ལན་མགྱོགས་པོ་སྤྲོད་དགོས།',
  'View comments' => 'མཆན་ལ་གཟིགས།',
  'Improve public reach' => 'མང་ཚོགས་ཀྱི་ཁྱབ་ཚད་མཐོར་འདེགས།',
  'Keep strong videos visible and refresh weak titles.' => 'བརྙན་འཕྲིན་ཤུགས་ཆེ་བ་མཐོང་ཐུབ་པ་དང་མིང་ཞན་པོ་གསར་པ་བསྐྲུན་དགོས།',
  'Explore tools' => 'ལག་ཆ་འཚོལ་ཞིབ་བྱེད་པ།',
  'Open the right workflow fast' => 'ཡང་དག་པའི་ལས་ཀའི་འགྲོ་ལུགས་མགྱོགས་མྱུར་ངང་ཁ་ཕྱེ།',
  'Upload planner' => 'ཡར་འཇོག་འཆར་འགོད་པ།',
  'Start a new upload with titles, tags, visibility, and thumbnail steps.' => 'མིང་བྱང་དང་རྟགས་མཚན་དང་མཐོང་ཐུབ་ཚད་དང་མཐེབ་གཞོང་གི་རིམ་པ་མཉམ་དུ་ཡར་བསྐུར་གསར་པ་འགོ་བཙུགས།',
  'Shorts studio' => 'གློག་བརྙན་ཐུང་གྲས་བཟོ་ཁང་།',
  'Create short videos for faster discovery and mobile viewers.' => 'གསར་རྙེད་མགྱོགས་པོ་དང་ཁ་པར་གྱི་ལྟ་མཁན་ལ་བརྙན་ཐུང་བཟོས།',
  'Content manager' => 'ནང་དོན་དོ་དམ་པ།',
  'Review visibility, monetization, comments, and performance in one place.' => 'མཐོང་ཐུབ་ཚད་དང་། དངུལ་བསགས། བསམ་ཚུལ། ལས་དོན་བཅས་ས་ཆ་གཅིག་ཏུ་བསྐྱར་ཞིབ་བྱས།',
  'Analytics review' => 'དབྱེ་ཞིབ་དཔྱད་ཞིབ།',
  'Track views, likes, comments, publishing status, and trends.' => 'ལྟ་ཚུལ་དང་དགའ་པོ་དང་མཆན་འགྲེམ་དང་དཔེ་སྐྲུན་གྱི་གནས་ཚུལ་དང་གོམ་སྟབས་རྗེས་འདེད་བྱོས།',
  'Channel profile' => 'རྒྱུད་ལམ་ངོ་སྤྲོད།',
  'Update your bio, channel details, and public creator presence.' => 'ཁྱེད་རང་གི་མི་ཚེའི་ལོ་རྒྱུས་དང་རྒྱུ་ལམ་གྱི་ཞིབ་ཕྲ་དང་སྤྱི་དམངས་གསར་གཏོད་ཀྱི་གནས་ཚུལ་གསར་བརྗེ་བྱོས།',
  'Audience building' => 'ལྟད་མོ་བ་འཛུགས་སྐྲུན།',
  'Study subscribers, comments, and what viewers respond to most.' => 'མངགས་ཉོ་བྱེད་མཁན་དང་མཆན་འགྲེལ་དང་ལྟ་མཁན་གྱིས་ལན་འདེབས་མང་ཤོས་བྱེད་པ་དེ་ཞིབ་འཇུག་བྱོས།',
  'Top content to learn from' => 'སློབ་སྦྱོང་བྱེད་སའི་ནང་དོན་གཙོ་བོ།',
  'Upload videos to unlock performance lessons.' => 'འཁྲབ་སྟོན་གྱི་སློབ་ཚན་ཁ་ཕྱེ་བའི་ཆེད་དུ་བརྙན་འཕྲིན་ཕབ་ལེན་བྱས།',
  'Tips to reach more viewers' => 'ལྟ་མཁན་མང་དུ་འགྲོ་བའི་ཐབས་ཤེས།',
  'Creator checklist' => 'བཟོ་མཁན་གྱི་ཞིབ་བཤེར་ཐོ་གཞུང་།',
  'Hook viewers in the first 3 seconds' => 'ཐོག་མའི་སྐར་ཆ་གསུམ་ནང་ལྟ་མཁན་ཧུག།',
  'Open with the result, conflict, or visual payoff before adding context.' => 'སྐབས་དོན་ཁ་སྣོན་མ་བྱེད་གོང་གྲུབ་འབྲས་དང་། འཁྲུག་རྩོད། ཡང་ན་མངོན་ཚུལ་གྱི་ཕན་འབྲས་བཅས་ཁ་ཕྱེ་དགོས།',
  'Make titles searchable' => 'ཁ་བྱང་འཚོལ་ཐུབ་པ་བཟོས།',
  'Use the exact words viewers would type, then keep the promise in the video.' => 'ལྟ་མཁན་གྱིས་ཡིག་འཇུག་བྱེད་པའི་ཚིག་དེ་བེད་སྤྱོད་བྱེད་དགོས། དེ་ནས་བརྙན་འཕྲིན་ནང་ཁས་ལེན་དེ་བསྲུང་དགོས།',
  'Convert shorts into sessions' => 'ཐུང་ཐུང་ཚོགས་ཐུན་དུ་བསྒྱུར།',
  'Pin a comment or description link from each short to a related full video.' => 'བརྙན་འཕྲིན་ཐུང་ཐུང་རེ་རེ་ནས་མཆན་འགྲེལ་ཡང་ན་འགྲེལ་བཤད་ཀྱི་འབྲེལ་མཐུད་དེ་འབྲེལ་ཡོད་བརྙན་ཐུང་ཆ་ཚང་ལ་སྦྱར་རོགས།',
  'Refresh underperforming uploads' => 'བྱེད་ནུས་མི་འདང་བའི་ཡར་བསྐུར་གསར་བརྗེ་བྱེད།',
  'Update thumbnails and titles after you have enough impressions to compare.' => 'ཁྱེད་ལ་འགྲན་རྩོད་བྱེད་པའི་མཐོང་སྣང་འདང་ངེས་ཤིག་བྱུང་རྗེས་མཐེབ་གཞོང་དང་འགོ་བརྗོད་གསར་བརྗེ་བྱེད་དགོས།',
  'Upload source' => 'ཡར་འཇུག་ཡོང་ཁུངས།',
  'Choose a local video file or import a public video from an enabled provider.' => 'ས་གནས་ཀྱི་བརྙན་འཕྲིན་ཡིག་ཆ་འདེམས་པའམ་ཡང་ན་ལྕོགས་ཅན་སྤྲོད་མཁན་ནས་སྤྱི་སྤྱོད་བརྙན་འཕྲིན་ནང་འདྲེན་བྱེད།',
  'Local upload' => 'ས་གནས་ཀྱི་ཕབ་ལེན།',
  'Import from URL' => 'URL ནས་ནང་འདྲེན།',
  'Import video from URL' => 'URLནས་བརྙན་ཐུང་ནང་འདྲེན།',
  'Select an enabled service and paste a public video URL. PlayHub will import it into the normal processing queue.' => 'ལྕོགས་ཅན་གྱི་ཞབས་ཞུ་འདེམས་ནས་སྤྱི་སྤྱོད་བརྙན་འཕྲིན་གྱི་URLསྦྱར་དགོས། PlayHub ཡིས་དེ་སྤྱིར་བཏང་གི་ལས་སྣོན་བང་རིམ་ནང་དུ་ནང་འདྲེན་བྱེད།',
  'Service' => 'ཞབས་ཞུ།',
  'Video URL' => 'བརྙན་འཕྲིན་དྲ་ཚིགས།',
  'Direct video URL' => 'ཐད་ཀའི་བརྙན་འཕྲིན་དྲ་ཚིགས།',
  'YouTube' => 'YouTube',
  'Vimeo' => 'Vimeo',
  'Dailymotion' => 'Dailymotion',
  'Imports a public MP4, MOV, WEBM, MKV, AVI, or M4V file URL.' => 'སྤྱི་སྤྱོད་MP4 དང་ MOV ཡང་ན་ WEBM དང་ MKV དང་ AVI ཡང་ན་ M4V ཡིག་ཆའི་URL ནང་འདྲེན་བྱེད།',
  'Requires a downloader command such as yt-dlp for media import.' => 'བརྡ་འཕྲིན་ནང་འདྲེན་བྱེད་པར་yt-dlpལྟ་བུའི་ཕབ་ལེན་བཀའ་ཚིག་དགོས།',
  'Import queue' => 'ནང་འདྲེན་བང་རིམ།',
  'Generated after import' => 'ནང་འདྲེན་བྱས་རྗེས་བསྐྲུན་པ།',
  'A thumbnail is created during processing.' => 'ལས་སྣོན་བྱེད་སྐབས་མཐེབ་གཞོང་ཞིག་བཟོས་ཡོད།',
  'Complete the import details first.' => 'སྔོན་ལ་ནང་འདྲེན་ཞིབ་ཕྲ་མཇུག་སྒྲིལ་དགོས།',
  'Import source' => 'ནང་འདྲེན་ཡོང་ཁུངས།',
  'Import summary' => 'ནང་འདྲེན་ཕྱོགས་བསྡུས།',
  'Source URL' => 'ཡོང་ཁུངས་URL',
  'Video imported' => 'བརྙན་ཐུང་ནང་འདྲེན་བྱས།',
  'Your video was imported and processing has started.' => 'ཁྱེད་ཀྱི་བརྙན་ཐུང་ནང་འདྲེན་བྱས་ནས་ལས་སྣོན་བྱེད་འགོ་ཚུགས་ཟིན།',
  'Import Video' => 'བརྙན་འཕྲིན་ནང་འདྲེན།',
  'Import a public video URL, customize its details, and publish it through the normal processing pipeline.' => 'སྤྱི་སྤྱོད་བརྙན་འཕྲིན་གྱི་URLནང་འདྲེན་བྱས་ནས་དེའི་ཞིབ་ཕྲ་སྒྲིག་བཀོད་བྱས་ནས་སྤྱིར་བཏང་གི་ལས་སྣོན་མདོང་ལམ་བརྒྱུད་ནས་པར་སྐྲུན་བྱེད།',
  'Video Import' => 'བརྙན་འཕྲིན་ནང་འདྲེན།',
  'Enable importing videos from supported external providers.' => 'རྒྱབ་སྐྱོར་བྱེད་པའི་ཕྱི་ཕྱོགས་མཁོ་སྤྲོད་བྱེད་མཁན་ནས་བརྙན་འཕྲིན་ནང་འདྲེན་བྱེད་ཐུབ།',
  'Downloader Command' => 'ཕབ་ལེན་བཀའ་བཀོད།',
  'YouTube Data API key' => 'ཡུ་ཏུབ་ཀྱི་གཞི་གྲངས་APIལྡེ་མིག',
  'Vimeo access token' => 'ཝི་མེའོ་འཛུལ་སྤྱོད་བརྡ་རྟགས།',
  'Dailymotion API key' => 'ཉིན་རེའི་གཡོ་འགུལ་APIལྡེ་མིག',
  'API Key' => 'API ལྡེ་མིག',
  'Not required' => 'དགོས་མཁོ་མེད།',
  'Save Import Settings' => 'ནང་འདྲེན་སྒྲིག་སྟངས་ཉར་ཚགས་བྱེད་པ།',
  'Video import settings saved.' => 'བརྙན་འཕྲིན་ནང་འདྲེན་སྒྲིག་སྟངས་ཉར་ཚགས་བྱས།',
  'Video import started.' => 'བརྙན་འཕྲིན་ནང་འདྲེན་བྱེད་འགོ་ཚུགས་ཡོད།',
  'This video import provider is disabled.' => 'བརྙན་འཕྲིན་ནང་འདྲེན་མཁོ་སྤྲོད་བྱེད་མཁན་འདི་བཀག་འགོག་བྱས་ཡོད།',
  'Video import provider is disabled.' => 'བརྙན་འཕྲིན་ནང་འདྲེན་མཁོ་སྤྲོད་བྱེད་མཁན་ལྕོགས་མིན་བཟོས་ཡོད།',
  'Direct imports must use a supported video file URL.' => 'ཐད་ཀར་ནང་འདྲེན་བྱེད་པར་ངེས་པར་དུ་རྒྱབ་སྐྱོར་བྱེད་པའི་བརྙན་འཕྲིན་ཡིག་ཆའི་URLབེད་སྤྱོད་གཏོང་དགོས།',
  'Cannot open remote video URL.' => 'ཐག་རིང་གི་བརྙན་འཕྲིན་ཁ་བྱང་ཁ་ཕྱེ་མི་ཐུབ།',
  'Cannot prepare imported video file.' => 'ནང་འདྲེན་བྱས་པའི་བརྙན་རིས་ཡིག་ཆ་གྲ་སྒྲིག་བྱེད་མི་ཐུབ།',
  'Cannot read remote video file.' => 'ཐག་རིང་གི་བརྙན་འཕྲིན་ཡིག་ཆ་ཀློག་མི་ཐུབ།',
  'Imported video exceeds the maximum upload size.' => 'ནང་འདྲེན་བྱས་པའི་བརྙན་ཐུང་ཆེས་མཐོའི་ཡར་འཇོག་ཚད་ལས་བརྒལ་ཡོད།',
  'Remote video file is empty.' => 'ཐག་རིང་གི་བརྙན་རིས་ཡིག་ཆ་སྟོང་པ་རེད།',
  'Video import downloader command is not configured.' => 'བརྙན་འཕྲིན་ནང་འདྲེན་ཕབ་ལེན་བཀའ་ཚིག་སྒྲིག་བཀོད་བྱས་མེད།',
  'Downloader did not create an importable video file.' => 'ཕབ་ལེན་པས་ནང་འདྲེན་བྱེད་ཐུབ་པའི་བརྙན་རིས་ཡིག་ཆ་གསར་བཟོ་བྱས་མེད།',
  'Import URL is invalid.' => 'ནང་འདྲེན་URLནུས་མེད་རེད།',
  'Import URL must use HTTP or HTTPS.' => 'ནང་འདྲེན་URLལ་ངེས་པར་དུ་HTTPཡང་ན་HTTPSབེད་སྤྱོད་གཏོང་དགོས།',
  'Import URL host is invalid.' => 'ནང་འདྲེན་URLགཙོ་བོ་ནུས་མེད་ཡིན།',
  'Import URL does not match the selected provider.' => 'ནང་འདྲེན་དྲ་གནས་དེ་འདེམས་སྒྲུག་བྱས་པའི་མཁོ་སྤྲོད་བྱེད་མཁན་དང་མཐུན་མི་ཐུབ།',
  'Import URL host cannot be resolved.' => 'ནང་འདྲེན་URLགཙོ་བོ་ཐག་གཅོད་བྱེད་མི་ཐུབ།',
  'Import URL must resolve to a public host.' => 'ནང་འདྲེན་URLདེ་སྤྱི་སྤྱོད་དྲ་ཚིགས་ལ་ཐག་གཅོད་བྱེད་དགོས།',
  'Unknown video import provider.' => 'བརྙན་འཕྲིན་ནང་འདྲེན་མཁོ་སྤྲོད་བྱེད་མཁན་མི་ཤེས་པ།',
  'Saves a public video file URL and plays it from the original URL.' => 'སྤྱི་སྤྱོད་བརྙན་འཕྲིན་ཡིག་ཆའི་URLཉར་ཚགས་བྱས་ནས་ཐོག་མའི་URLནས་གཏོང་ཐུབ།',
  'Fetches YouTube details and plays with the YouTube embed player.' => 'ཡུ་ཊུབ་ཀྱི་ཞིབ་ཕྲའི་གནས་ཚུལ་ལེན་ནས་ཡུ་ཊུབ་ཀྱི་བཙུགས་ཆས་དང་ལྷན་དུ་རྩེད་ཀྱི་ཡོད།',
  'Fetches Vimeo details and plays with the Vimeo embed player.' => 'ཝི་མེའོ་ཞིབ་ཕྲ་ལེན་ནས་ཝི་མེའོ་བཙུགས་པའི་སྒྲ་སྒམ་དང་མཉམ་དུ་རྩེད་ཀྱི་ཡོད།',
  'Fetches Dailymotion details and plays with the Dailymotion embed player.' => 'ཉིན་རེའི་འགུལ་སྐྱོད་ཀྱི་ཞིབ་ཕྲ་ལེན་ནས་ཉིན་རེའི་འགུལ་སྐྱོད་ཀྱི་བཙུགས་ཆས་དང་མཉམ་དུ་རྩེད་མོ་རྩེ།',
  'Select an enabled service and paste a public video URL. PlayHub will fetch the details and play it from the original provider.' => 'ལྕོགས་ཅན་གྱི་ཞབས་ཞུ་འདེམས་ནས་སྤྱི་སྤྱོད་བརྙན་འཕྲིན་གྱི་URLསྦྱར་དགོས། PlayHub ཡིས་ཞིབ་ཕྲའི་གནས་ཚུལ་བསྡུ་རུབ་བྱས་ནས་ཐོག་མའི་མཁོ་སྤྲོད་བྱེད་མཁན་ནས་གཏོང་རྒྱུ་རེད།',
  'Fetching...' => 'ལེན་བཞིན་ཡོད།',
  'Fetch details' => 'ཞིབ་ཕྲའི་གནས་ཚུལ་ལེན་པ།',
  'Unable to fetch provider details.' => 'མཁོ་སྤྲོད་བྱེད་མཁན་གྱི་ཞིབ་ཕྲའི་གནས་ཚུལ་ལེན་མི་ཐུབ།',
  'Saving provider video' => 'མཁོ་སྤྲོད་བྱེད་མཁན་གྱི་བརྙན་འཕྲིན་ཉར་ཚགས་བྱེད་པ།',
  'Fetched from provider' => 'མཁོ་སྤྲོད་བྱེད་མཁན་ནས་བླངས།',
  'Fetch details to preview' => 'སྔོན་ལྟའི་ཆེད་དུ་ཞིབ་ཕྲ་ལེན་པ།',
  'Provider thumbnails are saved as remote metadata.' => 'མཁོ་སྤྲོད་བྱེད་མཁན་གྱི་མཐེབ་གཞོང་རྣམས་ཐག་རིང་གི་མེ་ཊ་ཌེ་ཊ་ལྟར་ཉར་ཚགས་བྱས་ཡོད།',
  'External provider video' => 'ཕྱི་ཕྱོགས་མཁོ་སྤྲོད་བྱེད་མཁན་གྱི་བརྙན་འཕྲིན།',
  'Video import saved.' => 'བརྙན་འཕྲིན་ནང་འདྲེན་ཉར་ཚགས་བྱས།',
  'Could not read the provider video ID from this URL.' => 'URLའདི་ནས་མཁོ་སྤྲོད་བྱེད་མཁན་གྱི་བརྙན་འཕྲིན་ཨང་རྟགས་ཀློག་མ་ཐུབ།',
  'Import a public video URL, fetch provider details, and publish it with external playback.' => 'སྤྱི་སྤྱོད་བརྙན་འཕྲིན་གྱི་URLནང་འདྲེན་བྱས་ནས་མཁོ་སྤྲོད་བྱེད་མཁན་གྱི་ཞིབ་ཕྲ་ལེན་ནས་ཕྱི་རོལ་གྱི་བརྙན་འཕྲིན་དང་མཉམ་དུ་པར་སྐྲུན་བྱེད།',
  'Paste a video import URL' => 'བརྙན་འཕྲིན་ནང་འདྲེན་གྱི་URLསྦྱར།',
  'Remote import' => 'ཐག་རིང་ནང་འདྲེན།',
