  'Google and Apple sign-in' => 'གུ་གུལ་དང་ཀུ་ཤུའི་ནང་འཛུལ་བ།',
  'Enable Google and Apple OAuth for login and registration.' => 'ནང་འཇུག་དང་ཐོ་འགོད་ཆེད་དུ་གུ་གུལ་དང་ཨེ་པལ་OAuthལྕོགས་ཅན་བཟོས།',
  'Social sign-in expired. Try again.' => 'སྤྱི་ཚོགས་ཀྱི་ཐོ་འགོད་དུས་ཚོད་ཡོལ་ཡོད། ཡང་བསྐྱར་ཚོད་ལྟ་བྱོས།',
  'Google Sign-In is not configured.' => 'གུ་གུལ་ཐོ་འགོད་སྒྲིག་བཀོད་བྱས་མེད།',
  'Apple Sign-In is not configured.' => 'ཀུ་ཤུའི་ཐོ་འགོད་སྒྲིག་བཀོད་བྱས་མེད།',
  'Unable to finish social sign-in.' => 'སྤྱི་ཚོགས་ནང་འཇུག་མཇུག་སྒྲིལ་མི་ཐུབ།',
  'Unable to verify Google sign-in.' => 'གུ་གུལ་ཐོ་འགོད་ཞིབ་བཤེར་བྱེད་མི་ཐུབ།',
  'Unable to read your Google account details.' => 'ཁྱེད་ཀྱི་གུ་གུལ་ཁ་བྱང་ཞིབ་ཕྲ་ཀློག་མི་ཐུབ།',
  'Google did not return a verified email address.' => 'གུ་གུལ་གྱིས་བདེན་དཔང་བྱས་པའི་གློག་འཕྲིན་ཁ་བྱང་ཕྱིར་ལོག་བྱས་མེད།',
  'Unable to verify Apple sign-in.' => 'ཀུ་ཤུའི་ཐོ་འགོད་ཞིབ་བཤེར་བྱེད་མི་ཐུབ།',
  'Apple did not return a verified email address.' => 'ཀུ་ཤུ་ཡིས་བདེན་དཔང་བྱས་པའི་གློག་འཕྲིན་ཁ་བྱང་ཕྱིར་ལོག་བྱས་མེད།',
  'Apple private key is invalid.' => 'ཀུ་ཤུའི་སྒེར་གྱི་ལྡེ་མིག་ནུས་མེད་རེད།',
  'Social sign-in completed.' => 'སྤྱི་ཚོགས་ཀྱི་ཐོ་འགོད་མཇུག་སྒྲིལ་ཡོད།',
  'Log in with Facebook' => '在 Facebook 查看更多内容',
  'Sign up with Facebook' => 'ཕེས་བུཀ་ལ་ཐོ་འགོད།',
  'Google, Facebook and Apple sign-in' => 'གུ་གུལ་དང་ཕེས་སྦུག་དང་ཀུ་ཤུའི་ནང་འཛུལ་བ།',
  'Enable Google, Facebook and Apple OAuth for login and registration.' => 'ནང་འཇུག་དང་ཐོ་འགོད་ཆེད་དུ་གུ་གུལ་དང་། ཕེས་བུཀ། ཨེ་པལ་OAuthབཅས་ལྕོགས་ཅན་བཟོས།',
  'Facebook Login' => 'ངོ་དེབ་ནང་དུ་འཛུལ་བ།',
  'Facebook App ID' => 'ཕེས་བུཀ་མཉེན་ཆས་ཨང་རྟགས་',
  'Facebook App Secret' => 'ངོ་དེབ་མཉེན་ཆས་ཀྱི་གསང་བ།',
  'Facebook redirect URI' => 'ཕེས་སྦུག་བསྐྱར་ལོག་URI',
  'Facebook Login is not configured.' => 'Facebook ནང་འཇུག་སྒྲིག་བཀོད་བྱས་མེད།',
  'Unable to verify Facebook login.' => 'ངོ་དེབ་ནང་འཛུལ་བཤེར་བྱེད་མི་ཐུབ།',
  'Unable to read your Facebook account details.' => 'ཁྱེད་ཀྱི་ངོ་དེབ་ཁ་བྱང་ཞིབ་ཕྲ་ཀློག་མི་ཐུབ།',
  'Facebook did not return an email address.' => 'ཕེས་སྦུག་གིས་གློག་འཕྲིན་ཁ་བྱང་ལན་སྤྲད་མེད།',
  'Google' => 'Google',
  'Apple' => 'Apple',
  'The category update dialog is unavailable.' => 'སྡེ་ཚན་གསར་བཅོས་ཌའི་ལོག་དེ་ཐོབ་མི་ཐུབ།',
  'Choose the category to apply to content matching the current filters.' => 'ད་ལྟའི་ཚགས་རླུང་དང་མཐུན་པའི་ནང་དོན་ལ་འཇུག་སྤྱོད་བྱེད་པའི་སྡེ་ཚན་འདེམས།',
  'Update Categories' => 'རིགས་དབྱེ་གསར་བཅོས་བྱེད་པ།',
  'Updating...' => 'གསར་བཅོས་བྱེད་བཞིན་ཡོད།',
