  'Categories are configured.' => 'སྡེ་ཚན་སྒྲིག་བཀོད་བྱས་ཡོད།',
  'No content categories are configured yet.' => 'ད་དུང་ནང་དོན་གྱི་སྡེ་ཚན་སྒྲིག་བཀོད་བྱས་མེད།',
  'New category name' => 'སྡེ་ཚན་གསར་པའི་མིང་།',
  'Example: Tutorials' => 'དཔེར་ན། སློབ་ཁྲིད།',
  'Sort order' => 'དབྱེ་འབྱེད་གོ་རིམ།',
  'This updates all content matching current filters.' => 'འདིས་ད་ལྟའི་ཚགས་རླུང་ལ་མཐུན་པའི་ནང་དོན་ཚང་མ་གསར་བརྗེ་བྱེད།',
  'This updates all content because no filters are active.' => 'འདིས་ནང་དོན་ཚང་མ་གསར་བརྗེ་བྱེད་ཀྱི་ཡོད། རྒྱུ་མཚན་ནི་ཚགས་རླུང་གང་ཡང་ཤུགས་ལྡན་མིན།',
  'Video categories updated.' => 'བརྙན་འཕྲིན་གྱི་སྡེ་ཚན་གསར་བརྗེ་བྱས།',
  'Content category created.' => 'ནང་དོན་སྡེ་ཚན་བཟོས་ཡོད།',
