  'Category name' => 'སྡེ་ཚན་གྱི་མིང་།',
  'Save Category' => 'སྡེ་ཚན་ཉར་ཚགས།',
  'Content category updated.' => 'ནང་དོན་སྡེ་ཚན་གསར་བརྗེ་བྱས།',
  'Add or edit upload and content categories.' => 'ཡར་བསྐུར་དང་ནང་དོན་གྱི་སྡེ་ཚན་ཁ་སྣོན་ཡང་ན་བཟོ་བཅོས་བྱེད་པ།',
  'Invite creator' => 'གསར་གཏོད་པ་གདན་ཞུ།',
  'Create a creator account invite.' => 'གསར་གཏོད་པའི་རྩིས་ཁྲའི་མགྲོན་འབོད་བཟོས།',
  'Verify creators' => 'བཟོ་མཁན་ལ་བདེན་དཔང་བྱེད་པ།',
  'Enter creator email addresses, usernames, or handles to mark their accounts as verified.' => 'བཟོ་མཁན་གྱི་གློག་འཕྲིན་ཁ་བྱང་དང་། སྤྱོད་མཁན་གྱི་མིང་། ཡང་ན་ལག་ཆ་བླུགས་ནས་ཁོང་ཚོའི་རྩིས་ཁྲ་དེ་བདེན་དཔང་བྱས་པ་ཡིན་པར་རྟགས་བཀོད་དགོས།',
  'Creator emails or handles' => 'བཟོ་མཁན་གྱི་གློག་འཕྲིན་ཡང་ན་ལག་འཛིན།',
  'creator@example.com, @creator-handle' => 'creator@example.com, @creator-handle',
  'Send creator announcement' => 'བཟོ་མཁན་གྱི་གསལ་བསྒྲགས་བསྐུར།',
  'Send an announcement email to all creator accounts.' => 'གསར་གཏོད་བྱེད་མཁན་གྱི་རྩིས་ཁྲ་ཚང་མར་གསལ་བསྒྲགས་གློག་འཕྲིན་གཏོང་དགོས།',
  'Send announcement' => 'གསལ་བསྒྲགས་བསྐུར།',
  'Enter at least one creator email, username, or handle.' => 'ཉུང་མཐར་ཡང་གསར་གཏོད་བྱེད་མཁན་གྱི་གློག་འཕྲིན་དང་སྤྱོད་མཁན་གྱི་མིང་ཡང་ན་ལག་ཆ་གཅིག་བླུགས།',
  'Email delivery is not configured. Configure MAIL_* settings before sending creator announcements.' => 'གློག་འཕྲིན་སྐྱེལ་འདྲེན་སྒྲིག་བཀོད་བྱས་མེད། གསར་གཏོད་པའི་གསལ་བསྒྲགས་མ་གཏོང་གོང་ལ་MAIL_*སྒྲིག་སྟངས་སྒྲིག་བཀོད་བྱོས།',
  'Creators verified.' => 'བཟོ་མཁན་གྱིས་བདེན་དཔང་བྱས།',
  'Creator announcement sent.' => 'བཟོ་མཁན་གྱི་གསལ་བསྒྲགས་བཏང་ཡོད།',
  'Create new role' => 'འགན་འཁྲི་གསར་པ་གཏོད་པ།',
