  'Save group' => 'སྡེ་ཚན་སྲུང་བ།',
  'Role name' => 'འགན་འཁྲིའི་མིང་།',
  'What this role can do' => 'འཁྲབ་སྟོན་འདིས་ཅི་ཞིག་བྱེད་ཐུབ་བམ།',
  'Permission group' => 'ཆོག་མཆན་སྡེ་ཚན།',
