  'Topbar height' => 'སྟེང་ཐིག་གི་མཐོ་ཚད།',
  'Ultra-low latency' => 'འགོར་འགྱངས་ཤིན་ཏུ་དམའ་བ།',
  'Upload speed' => 'ཡར་འཇུག་མྱུར་ཚད།',
  'User message' => 'སྤྱོད་མཁན་གྱི་བརྡ་འཕྲིན།',
  'user@example.com, creator@example.com' => 'བེད་སྤྱོད་པ་@དཔེ་མཚོན། གསར་གཏོད་པ་@དཔེ་མཚོན།',
  'Webcam preview' => 'དྲ་རྒྱའི་པར་ཆས་སྔོན་ལྟ།',
  'Webcam preview works locally. Public broadcasting and RTMP credentials will be added with the streaming engine.' => 'དྲ་རྒྱའི་པར་ཆས་ཀྱི་སྔོན་ལྟ་དེ་ས་གནས་སུ་ལས་ཀ་བྱེད་ཀྱི་ཡོད། སྤྱི་དམངས་རྒྱང་བསྒྲགས་དང་RTMPཡི་ཆོག་མཆན་དེ་འཕྲིན་གཏོང་འཕྲུལ་འཁོར་དང་མཉམ་དུ་ཁ་སྣོན་བྱ་རྒྱུ་རེད།',
  'Website Colors' => 'དྲ་ཚིགས་ཀྱི་ཁ་དོག',
  'Website Configuration' => 'དྲ་ཚིགས་སྒྲིག་བཀོད།',
  'Website configuration not saved' => 'དྲ་ཚིགས་སྒྲིག་བཀོད་ཉར་ཚགས་བྱས་མེད།',
  'Write the reply that will be saved and emailed to the user...' => 'ལན་འདེབས་དེ་ཉར་ཚགས་བྱས་ནས་སྤྱོད་མཁན་ལ་གློག་འཕྲིན་གཏོང་རྒྱུ་ཡིན་པ་བྲིས།',
  'Your studio settings can be prepared now. Public broadcasting will be enabled with the media engine.' => 'ཁྱེད་རང་གི་གློག་བརྙན་ཁང་གི་སྒྲིག་བཀོད་ད་ལྟ་གྲ་སྒྲིག་བྱེད་ཐུབ། སྨྱན་བྱད་འཕྲུལ་འཁོར་ལ་བརྟེན་ནས་སྤྱི་པའི་རྒྱང་སྒྲོག་བྱེད་ཐུབ།',
  'Activate poll' => 'དམངས་འདོད་བསྡུ་ལེན་བྱེད་ཤུགས་ཆེ་རུ་གཏོང་བ།',
  'Cancel edit' => 'རྩོམ་སྒྲིག་མེད་པར་བཟོས།',
  'Close poll' => 'འོས་བསྡུ་ཁ་རྒྱག་པ།',
  'Creator defaults' => 'བཟོ་མཁན་གྱི་སྔོན་སྒྲིག',
  'Edit poll' => 'དམངས་འདོད་ཞིབ་འཇུག་རྩོམ་སྒྲིག།',
  'Save poll' => 'དམངས་འདོད་བསྡུ་ལེན་སྲུང་བ།',
  'Schedule poll' => 'འདེམས་ཤོག་འཕེན་པའི་དུས་ཚོད།',
  'Webcam preview is disabled by the site administrator.' => 'དྲ་ཚིགས་དོ་དམ་པས་དྲ་རྒྱའི་པར་ཆས་ཀྱི་སྔོན་ལྟ་བཀག་འགོག་བྱས་ཡོད།',
  'WebRTC engine configured on this server' => 'དྲ་ཚིགས་འདིའི་ཐོག་དྲ་རྒྱའི་RTCའཕྲུལ་འཁོར་སྒྲིག་བཀོད་བྱས།',
  'Set the LiveKit server credentials to enable broadcasting' => 'རྒྱང་བསྒྲགས་བྱེད་ཐུབ་པའི་ཆེད་དུ་LiveKitསར་བར་གྱི་ཆོག་མཆན་སྒྲིག་དགོས།',
  'LiveKit WebRTC is ready for browser broadcasting.' => 'LiveKit WebRTC ནི་དྲ་ངོས་རྒྱང་བསྒྲགས་བྱེད་པར་གྲ་སྒྲིག་ཡིན།',
  'Webcam preview works locally. Public broadcasting requires the LiveKit media engine.' => 'དྲ་རྒྱའི་པར་ཆས་ཀྱི་སྔོན་ལྟ་དེ་ས་གནས་སུ་ལས་ཀ་བྱེད་ཀྱི་ཡོད། སྤྱི་དམངས་རྒྱང་བསྒྲགས་ལ་LiveKitབརྡ་འཕྲིན་འཕྲུལ་འཁོར་དགོས།',
  'You are live' => 'ཁྱེད་རང་གསོན་པོར་ཡོད།',
  'Your camera and microphone are publishing through LiveKit.' => 'ཁྱེད་ཀྱི་པར་ཆས་དང་སྐད་འཕྲིན་དེ་ཚོ་LiveKitབརྒྱུད་ནས་པར་སྐྲུན་བྱེད་ཀྱི་ཡོད།',
  'Ending...' => 'མཇུག་སྒྲིལ།',
  'End live stream' => 'ཐད་གཏོང་མཇུག་སྒྲིལ།',
  'Connecting to live stream...' => 'ཐད་གཏོང་ལ་མཐུད་བཞིན་ཡོད།',
  'This stream has not started yet.' => 'རྒྱུག་ཆུ་འདི་ད་དུང་འགོ་ཚུགས་མེད།',
  'No chat messages yet.' => 'ད་དུང་ཁ་བརྡ་འཕྲིན་ཡིག་མེད།',
  'Sign in to join live chat' => 'ཐད་གཏོང་ཁ་བརྡ་ལ་ཞུགས་ཆེད་ཐོ་འགོད་བྱོས།',
  'Creator goal' => 'བཟོ་མཁན་གྱི་དམིགས་ཡུལ།',
  'Unable to connect to this live stream.' => 'ཐད་གཏོང་འདི་ལ་མཐུད་མི་ཐུབ།',
  'Unable to send the chat message.' => 'ཁ་བརྡའི་འཕྲིན་ཐུང་གཏོང་མི་ཐུབ།',
  'Unable to start the live stream.' => 'ཐད་གཏོང་འགོ་འཛུགས་མི་ཐུབ།',
  'Unable to end the live stream.' => 'ཐད་གཏོང་མཇུག་སྒྲིལ་མི་ཐུབ།',
  'LiveKit connection details are unavailable.' => 'LiveKit མཐུད་ཁའི་ཞིབ་ཕྲ་མེད་པ་རེད།',
  'A working camera and microphone are required to start broadcasting.' => 'བརྙན་འཕྲིན་གཏོང་འགོ་ཚུགས་པར་ལས་ཀ་བྱེད་བཞིན་པའི་པར་ཆས་དང་སྐད་འཕྲིན་དགོས།',
  'Start the camera preview and allow camera and microphone access before broadcasting.' => 'པར་ཆས་ཀྱི་སྔོན་ལྟ་འགོ་འཛུགས་ནས་རྒྱང་བསྒྲགས་མ་བྱས་གོང་པར་ཆས་དང་སྐད་འཕྲིན་ལ་འཛུལ་ཆོག',
  'LiveKit WebRTC currently requires the webcam source.' => 'ད་ལྟ་LiveKit WebRTC ལ་དྲ་རྒྱའི་པར་ཆས་ཀྱི་འབྱུང་ཁུངས་དགོས།',
  'Start the live stream before activating its media source.' => 'བརྡ་འཕྲིན་གྱི་ཐོན་ཁུངས་ཤུགས་སྣོན་མ་གཏོང་གོང་ཐད་གཏོང་འགོ་འཛུགས།',
  'LiveKit is not configured.' => 'ལིབ་ཀིཊ་སྒྲིག་བཀོད་བྱས་མེད།',
  'Sign in to watch this live stream.' => 'ཐད་གཏོང་འདི་ལ་ལྟ་བར་ཐོ་འགོད་བྱོས།',
  'LiveKit server configuration' => 'LiveKit སར་བར་སྒྲིག་བཀོད།',
  'Docker image' => 'ཌོག་ཀར་གྱི་པར་རིས།',
  'Container status' => 'སྣོད་ཀྱི་གནས་ཚུལ།',
  'Running' => 'རྒྱུག་པ།',
  'Stopped' => 'བཀག་ཡོད།',
  'WebRTC engine is accepting connections' => 'WebRTCའཕྲུལ་འཁོར་གྱིས་མཐུད་སྣེ་དང་ལེན་བྱེད་བཞིན་ཡོད།',
  'Save configuration to request a container restart' => 'སྣོད་ཆས་བསྐྱར་དུ་འགོ་འཛུགས་པའི་རེ་འདུན་ཆེད་དུ་སྒྲིག་བཀོད་ཉར་ཚགས་བྱེད།',
  'Enable LiveKit server' => 'LiveKitསར་བར་ལྕོགས་ཅན་བཟོས།',
  'LiveKit WebSocket URL' => 'ལིབ་ཀིཊ་དྲ་རྒྱའི་སོ་ཀེཊ་URL',
  'LiveKit API key' => 'ལིབ་ཀིཊ་ཨེ་པི་ཨའི་ལྡེ་མིག',
  'LiveKit API secret' => 'ལིབ་ཀིཊ་ཨེ་པི་ཨའི་གསང་བ།',
  'API secret configured. Leave blank to keep the current secret.' => 'APIགསང་བ་སྒྲིག་བཀོད་བྱས། ད་ལྟའི་གསང་བ་ཉར་བའི་ཆེད་དུ་སྟོང་ཆ་བཞག་དགོས།',
  'Minimum 32 characters' => 'ཡིག་འབྲུ་ ༣༢ ཉུང་མཐའ།',
  'Signaling port' => 'བརྡ་རྟགས་འདྲེན་ཁང༌།',
  'TLS is provided by the website Nginx proxy' => 'TLSནི་དྲ་ཚིགས་Nginxངོ་ཚབ་ཀྱིས་མཁོ་སྤྲོད་བྱས།',
  'WebRTC TCP port' => 'དྲ་རྒྱའི་RTC TCP མཐུད་ཁ།',
  'WebRTC UDP port range start' => 'WebRTC UDP འདྲེན་ལམ་ཁྱབ་ཁོངས་འགོ་འཛུགས།',
  'WebRTC UDP port range end' => 'WebRTC UDP མཐུད་ཁའི་ཁྱབ་ཁོངས་མཇུག་སྒྲིལ།',
  'Discover public IP using STUN' => 'STUN བཀོལ་ནས་སྤྱི་པའི་IP འཚོལ་ཞིབ་བྱས།',
  'Public node IPv4 override' => 'སྤྱི་པའི་མཛུབ་མོ་IPv4བཀག་འགོག',
  'Optional when STUN discovery is enabled' => 'STUN གསར་རྙེད་ལྕོགས་ཅན་བཟོས་སྐབས་འདམ་ཀ་ཡིན།',
  'LiveKit region' => 'ལིབ་ཀིཊ་ས་ཁུལ།',
  'Optional region identifier' => 'གདམ་ཀའི་ས་ཁུལ་ངོས་འཛིན།',
  'LiveKit log level' => 'LiveKit དྲན་ཐོའི་གནས་རིམ།',
  'Debug' => 'རྐྱེན་སེལ་བ།',
  'Info' => 'ཆ་འཕྲིན།',
  'Warning' => 'ཉེན་བརྡ།',
  'Error' => 'ནོར་འཁྲུལ།',
  'Empty room timeout (seconds)' => 'ཁང་མིག་སྟོང་པའི་དུས་ཚོད་རྫོགས་སོང་(སྐར་ཆ)',
  'Participant departure timeout (seconds)' => 'མཉམ་ཞུགས་པ་ཐོན་པའི་དུས་ཚོད་རྫོགས་སོང་(སྐར་ཆ)',
  'Maximum participants per room' => 'ཁང་མིག་རེར་མཉམ་ཞུགས་བྱེད་མཁན་མང་ཤོས།',
  '0 means unlimited' => '0 ནི་ཚད་མེད་ཡིན།',
  'Generated configuration' => 'བསྐྲུན་པའི་སྒྲིག་བཀོད།',
  'Stored inside the PlayHub project' => 'PlayHub ལས་གཞིའི་ནང་དུ་ཉར་ཚགས་བྱས་ཡོད།',
  'Live streaming settings saved. LiveKit container restart requested.' => 'ཐད་གཏོང་སྒྲིག་སྟངས་ཉར་ཚགས་བྱས། LiveKit སྣོད་ཆས་བསྐྱར་དུ་འགོ་འཛུགས་དགོས་པའི་རེ་འདུན་བཏོན་ཡོད།',
  'LiveKit UDP port range end must be greater than or equal to its start.' => 'LiveKit UDP འདྲེན་ལམ་གྱི་ཁྱབ་ཁོངས་མཇུག་དེ་འགོ་འཛུགས་ལས་ཆེ་བའམ་འདྲ་མཉམ་དགོས།',
  'LiveKit server is not running.' => 'LiveKit ཞབས་ཞུ་འཕྲུལ་ཆས་དེ་གཡོག་བཞིན་མེད།',
  'Container ID' => 'དོས་ཁང་གི་ཨང་རྟགས།',
  'Image ID' => 'པར་རིས་ID',
